pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();
        vm.prank(alice);
        c.withdrawAll();
        // After withdrawAll, reference decrements balance to 0, buggy does not
        // Now deposit again: buggy still has balance 1 ether from first deposit
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();
        // Reference: balance = 0 + 1 ether = 1 ether
        // Buggy: balance = 1 ether (never decremented) + 1 ether = 2 ether
        // So buggy has balance 2 ether while reference has 1 ether
        assertTrue(c.balance() == 1 ether);
    }
}

