pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        address bob = address(0x5678);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 1 ether);

        // Alice deposits and withdraws all
        vm.prank(alice);
        c.deposit{value: 1 ether}();
        vm.prank(alice);
        c.withdrawAll();

        // Bob deposits and tries to withdraw all
        vm.prank(bob);
        c.deposit{value: 1 ether}();
        vm.prank(bob);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // In the reference, bob's withdrawal succeeds (ok == true) and c has balance 0.
        // In the buggy version, balance is not decremented after alice's withdrawal,
        // so c's balance is 2 ether, but only 1 ether is actually present, causing the
        // withdrawal's external call to fail (ok == false) or revert. Here we check the revert status.
        assertTrue(ok);
    }
}

