pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);

        // First deposit: 1 ether
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        // First withdrawal (with the bug, credit is zeroed before balance update, so balance update works correctly on first call)
        vm.prank(alice);
        c.withdrawAll();

        // Second deposit: 1 ether
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        // Second withdrawal: reference succeeds, buggy causes revert
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // Reference: withdrawAll succeeds, c.balance becomes 0
        // Bug: withdrawAll reverts (underflow because balance was already decremented incorrectly)
        assertTrue(ok);
    }
}

