pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up non-payable address
        address nonPayable = address(0x1234);
        // Fund the contract with 1 wei via payable msg.sender
        address payableCaller = address(this);
        vm.deal(payableCaller, 1 wei);
        vm.prank(payableCaller);
        c.deposit{value: 1 wei}();

        // Attempt withdrawal from non-payable address (will revert due to call failure)
        vm.prank(nonPayable);
        (bool success1, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // Now the reference keeps credit[nonPayable]=1, bug sets it to 0

        // Withdraw from the original caller: reference succeeds, bug reverts (underflow)
        vm.prank(payableCaller);
        (bool success2, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // Reference: success2 = true, bug: success2 = false
        assertTrue(success2);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address payable depositor = payable(address(0x123));
        address nonPayable = address(0x456);

        // Fund depositor with 1 wei
        vm.deal(depositor, 1 wei);

        // Depositor deposits 1 wei
        vm.prank(depositor);
        c.deposit{value: 1 wei}();

        // Now attempt withdrawal from non-payable address (which will revert)
        vm.prank(nonPayable);
        // This will revert because nonPayable cannot receive ether — we catch it
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Now depositor tries to withdraw again
        vm.prank(depositor);
        bool ok2;
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // In the reference contract, the failed withdrawal did NOT reset credit[depositor],
        // so the second withdrawal succeeds and depositor gets 1 wei.
        // In the buggy contract, credit[depositor] was set to 0 before the revert,
        // so the second withdrawal does nothing (oCredit = 0, the if block is skipped).
        // Thus after both attempts, the depositor should have its original 1 wei back in reference,
        // but in buggy it still has 1 wei in the contract (since second withdrawal did nothing).
        // So we check that depositor's balance is 1 wei after both attempts — for reference it is 2 wei (the original + 1 received), for bug it is 1 wei.
        // But easier: check contract balance. For reference, contract balance is 0 (depositor got the money back). For bug, contract balance is 1 wei (depositor never got it).
        assertTrue(address(c).balance == 0 wei);
    }
}

